INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('ecced887-a7a4-45de-b4ce-8e9d9475fabd', '21feff02-016d-46e2-bb9d-c27495133b1b', '57. óra: Tengelyes tükrözés', 'Tengelyes tükrözés fogalma, tengely (t), tárgy és tükörkép (A és A'').', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "27ed890b-1bb2-4256-bb61-862d5ef3746e", "text": "Mi a tengelyes tükrözés lényege egy ''t'' tengelyre nézve?", "type": "multiple-choice", "options": [{"id": "a9908ab0-0ad1-4e41-9ee9-b2cb3a6b7a9b", "text": "A pont és tükörképe a tengelyre merőleges egyenesen van, és egyenlő távolságra van a tengelytől", "isCorrect": true}, {"id": "014226dd-242d-48a7-bf81-a136b4a4cd7f", "text": "A pontot eltoljuk párhuzamosan", "isCorrect": false}, {"id": "077f858b-4b6e-4a88-89f4-02fe5ae98ebf", "text": "A pontot elforgatjuk 180 fokkal", "isCorrect": false}, {"id": "12212b99-1ed8-42c2-9ea4-9d3393356032", "text": "A pontot lefelé mozgatjuk 5 cm-rel", "isCorrect": false}], "timeLimit": 15}, {"id": "a5e4db24-031a-46d4-bea6-55db56d8ca5d", "text": "Hol van a tengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "d842ad7d-f603-48ea-8397-3ea176422737", "text": "Önmagában (fixpont)", "isCorrect": true}, {"id": "3e8ca806-a0a0-41d3-af2e-d65964abd64d", "text": "Az origóban", "isCorrect": false}, {"id": "13e2aec0-b98e-47f3-91db-3a549eb21ed9", "text": "Végtelenben", "isCorrect": false}, {"id": "84e2aa91-ef6d-4dd6-bbfe-a3b170253805", "text": "A tengely másik végén", "isCorrect": false}], "timeLimit": 15}, {"id": "4625586f-1ec5-40c8-93e2-51113ef12da9", "text": "Ha a P pont 4 cm-re van a tükörtengelytől, milyen messze van a P'' tükörkép a tengelytől?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "148c1f70-c298-4e5c-85f2-81482352befe", "text": "Milyen messze van a P pont a P'' tükörképétől, ha a tengelytől való távolsága 4 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "a368f4c2-3a5a-4f32-9fba-d5388e982b98", "text": "A tengelyes tükrözés egybevágósági transzformáció.", "type": "true-false", "options": [{"id": "c78df42d-585a-4da8-916e-c3b637b26be0", "text": "Igaz", "isCorrect": true}, {"id": "e903ed43-1301-48c7-901a-79ca6c861902", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "83fbd553-6586-4ee1-8ddb-f448b3c2c4f6", "text": "A tengelyes tükrözés megváltoztatja az alakzat körüljárási irányát (pl. óramutató járásával megegyezőből ellentétes lesz).", "type": "true-false", "options": [{"id": "ad7977db-34d2-4204-a17b-5d9573cd6f75", "text": "Igaz", "isCorrect": true}, {"id": "90d268f1-852d-4b76-816d-89275b1d35ce", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5d25b49c-2f1a-44cc-8dd5-11b19250a6b2", "text": "A tengelyesen tükrös alakzat és tükörképe egybevágó.", "type": "true-false", "options": [{"id": "3887b9aa-00a9-4b65-b650-718929f5b977", "text": "Igaz", "isCorrect": true}, {"id": "552720c5-81cb-44ce-acde-b2382bf62c76", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('e488f6f2-3145-4019-9219-d95632d2179f', '21feff02-016d-46e2-bb9d-c27495133b1b', '58. óra: A tengelyes tükrözés tulajdonságai', 'Távolságtartás, szögtartás, körüljárási irány megváltozása, egyenes és kör tükörképe.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "44dd6366-065d-4dab-8bfe-ce36fd151223", "text": "Melyik tulajdonság érvényes a tengelyes tükrözésre?", "type": "multiple-choice", "options": [{"id": "0fa0da92-1099-4dad-bfd3-4aa0f3f10d4b", "text": "Távolságtartó, szögtartó, egyenestartó és megváltoztatja a körüljárási irányt", "isCorrect": true}, {"id": "c364a0a2-4305-4ba0-9533-1ce80754d840", "text": "Növeli a szakaszok hosszát", "isCorrect": false}, {"id": "39afff78-4770-41fa-adcf-a423c29b3ef5", "text": "Megváltoztatja a szögek nagyságát", "isCorrect": false}, {"id": "66975331-b8a0-4cf8-9fdb-7878a18a50ef", "text": "Négyszögből háromszöget csinál", "isCorrect": false}], "timeLimit": 15}, {"id": "9276cead-b7a7-423a-bf05-0b00b5045727", "text": "Egy 5 cm-es szakasz tengelyes tükörképe is 5 cm hosszú.", "type": "true-false", "options": [{"id": "a2862ae1-13b4-45c0-9e66-24a509308aca", "text": "Igaz (távolságtartó)", "isCorrect": true}, {"id": "ba1a26b8-e4ce-41c6-b536-4504bfc6506f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e29f7729-817b-4b36-bfed-f6d1a95dad31", "text": "Egy 45°-os szög tengelyes tükörképe is 45°-os.", "type": "true-false", "options": [{"id": "050541e9-2880-45c7-813c-55690f471ed0", "text": "Igaz (szögtartó)", "isCorrect": true}, {"id": "cb6656c9-2a3c-4df2-90be-3e33861fe6ec", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "23f4eca3-0301-4d83-a496-600bd2ba8866", "text": "A tengelyre merőleges egyenes tükörképe önmaga (önmagába transzformálódik).", "type": "true-false", "options": [{"id": "f03ff906-b646-42b2-9b36-973bcb2d525a", "text": "Igaz", "isCorrect": true}, {"id": "116cdce3-aa76-4c06-860b-111a00b788c7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "25a4f20a-b615-416a-a536-fa6292499460", "text": "Egy kör tengelyes tükörképe ugyanolyan sugarú kör.", "type": "true-false", "options": [{"id": "8013d32b-3bb2-4aa3-a1f7-39a9984d9013", "text": "Igaz", "isCorrect": true}, {"id": "3d18f0b3-5680-439f-90fc-d355d669ae79", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "076768b3-f902-46a2-92ab-bec8bd8b96b1", "text": "A tengellyel párhuzamos egyenes tükörképe is párhuzamos a tengellyel.", "type": "true-false", "options": [{"id": "88ac94fd-8271-46d9-88bc-350b720f4404", "text": "Igaz", "isCorrect": true}, {"id": "a7a5af5d-65e8-4316-8070-1b5f910251b8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8daf8e09-d63b-4032-9472-96f00a948496", "text": "Hány fixpontja (helyben maradó pontja) van a tengelyes tükrözésnek a síkban?", "type": "multiple-choice", "options": [{"id": "a94a97b7-7c15-4dba-a3b4-deba0f2512a7", "text": "Végtelen sok (a tükörtengely minden pontja)", "isCorrect": true}, {"id": "a2ee81f7-800e-4a7b-8972-91db7a989408", "text": "Csak 1", "isCorrect": false}, {"id": "72cf9ef8-4f3f-422d-9d56-f487f946e8d6", "text": "Nincs egy sem", "isCorrect": false}, {"id": "8de5d710-9272-4dcb-b00f-81d460fc3cd2", "text": "Pontosan 2", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('2b23c494-6497-4036-a807-b735e20122c4', '21feff02-016d-46e2-bb9d-c27495133b1b', '59. óra: Gyakorlóóra', 'Tengelyes tükörkép szerkesztésének gyakorlása pontok, szakaszok, sokszögek esetén.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "a421148c-ace5-4859-b053-581f26e9ab35", "text": "Hogyan szerkesztjük meg egy P pont ''t'' tengelyre vonatkozó tükörképét?", "type": "multiple-choice", "options": [{"id": "1fd0a2dc-1836-4a40-ab27-3889e2037414", "text": "Merőlegest állítunk P-ből ''t''-re, és a talpponttól felmérjük a P távolságát a merőlegesre", "isCorrect": true}, {"id": "687e7362-d0b3-4a33-9f41-d01cafc05593", "text": "Párhuzamost húzunk ''t''-vel", "isCorrect": false}, {"id": "d2f338d8-8f2a-4863-a736-70ff351f1764", "text": "Körzővel kört rajzolunk P középponttal", "isCorrect": false}, {"id": "47a49a91-929b-4d81-9f30-4c9fe143437a", "text": "Összekötjük P-t az origóval", "isCorrect": false}], "timeLimit": 15}, {"id": "57e1ed31-d2a8-4d46-8a5d-58cca73969c6", "text": "Egy háromszög tengelyes tükrözése után a kapott háromszög területe megegyezik az eredetivel.", "type": "true-false", "options": [{"id": "4fe9ae36-43b8-4129-a79f-772116db5b43", "text": "Igaz", "isCorrect": true}, {"id": "f36268aa-56d1-4413-a5be-e4ba14ca904a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c9b53da1-7382-45f9-a466-7b8ee3e1daa3", "text": "Ha a P pont a tengelyen van, hol van a tükörképe?", "type": "multiple-choice", "options": [{"id": "895e7268-6bbf-4c2d-b290-50f948008d71", "text": "Önmagában (P = P'')", "isCorrect": true}, {"id": "7e0d6455-f000-40ee-9d50-cced4597e46d", "text": "A tengely másik oldalán", "isCorrect": false}, {"id": "4ebf3e51-1ae7-4972-91ae-a896cea8ba64", "text": "A sík szélén", "isCorrect": false}, {"id": "d71880e8-35a3-44ad-957d-45b119623313", "text": "Az origóban", "isCorrect": false}], "timeLimit": 15}, {"id": "f3081e30-3fec-47d5-96f4-16267eb14916", "text": "A szakasz felezőmerőlegese a szakaszt önmagára tükrözi vissza.", "type": "true-false", "options": [{"id": "28ac5338-d836-430b-96a8-b1310d8f5fba", "text": "Igaz", "isCorrect": true}, {"id": "699b780c-907a-41d9-9251-756f398983d4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5914ec80-7826-445a-954a-6efabf919bf4", "text": "Melyik betűnek VAN függőleges szimmetriatengelye? (pl. A, M, Y, W)", "type": "multiple-choice", "options": [{"id": "9552bbb8-c211-42d2-8c3d-68e25da063b5", "text": "A", "isCorrect": true}, {"id": "73c99c48-d39d-43cb-a4f8-c8daf8cdfbb5", "text": "F", "isCorrect": false}, {"id": "4e6065e0-14d7-4559-bb7f-fa0be2396480", "text": "L", "isCorrect": false}, {"id": "4ac67a5e-2ee1-478a-a509-52b930bd53d9", "text": "R", "isCorrect": false}], "timeLimit": 15}, {"id": "4a7e49be-141d-4e43-b566-bd2ef193a3ea", "text": "Melyik betűnek VAN vízszintes szimmetriatengelye? (pl. B, C, D, E, K)", "type": "multiple-choice", "options": [{"id": "b8e9acb3-f4c7-44d0-97ed-9dd289a91104", "text": "E", "isCorrect": true}, {"id": "28524713-ed18-4f1f-a189-1070f8586458", "text": "F", "isCorrect": false}, {"id": "f434d2f9-dcd9-47ed-96b1-8962388fb536", "text": "G", "isCorrect": false}, {"id": "ab12699e-c663-4003-9a4f-9648094d547b", "text": "J", "isCorrect": false}], "timeLimit": 15}, {"id": "2b85c8ea-4e36-4097-bc46-d1f1f224c287", "text": "A tengelyesen tükrös alakzatok szimmetrikusak a tükörtengelyre.", "type": "true-false", "options": [{"id": "f20fc5de-591a-4983-ac13-812f068f2b2a", "text": "Igaz", "isCorrect": true}, {"id": "5f1d3256-aebf-46ff-b1b5-a08ce4ef2521", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('70883564-37ad-4a77-9fb3-e82b2eebc924', '21feff02-016d-46e2-bb9d-c27495133b1b', '60. óra: Tengelyes szimmetria', 'Tengelyesen szimmetrikus alakzatok, szögfelező és felezőmerőleges szimmetriatengelyként.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "781199bb-dbc2-4ba2-aa44-2b024ad213cd", "text": "Mikor nevezünk egy síkidomot tengelyesen szimmetrikusnak?", "type": "multiple-choice", "options": [{"id": "a006d5e8-1144-4aeb-8e2c-b8856ceac9b9", "text": "Ha van legalább egy olyan egyenes (szimmetriatengely), amelyre tükrözve a síkidom önmagába megy át", "isCorrect": true}, {"id": "8f716a2a-5f62-40bc-b280-a357bed265af", "text": "Ha minden oldala egyenlő", "isCorrect": false}, {"id": "bf28e6fa-c8d4-4f5c-82d1-7a1dcca39481", "text": "Ha kerek", "isCorrect": false}, {"id": "584ce104-e642-4c86-8c90-95b2180d8480", "text": "Ha nincs szöge", "isCorrect": false}], "timeLimit": 15}, {"id": "c2f743be-0f16-438a-a91a-44bf69337844", "text": "Mi a szögfelező egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "68150248-4ce9-494c-ae40-6be510304f89", "text": "A szögtartományt két egyenlő szögre osztja, és pontjai egyenlő távolságra vannak a szög száraitól", "isCorrect": true}, {"id": "4807178c-db88-4ed6-ad46-bbeb16964ff5", "text": "A szög szárait meghosszabbítja", "isCorrect": false}, {"id": "c0be4a70-0e6d-4089-871a-5dd708b76dcc", "text": "Merőleges a szög száira", "isCorrect": false}, {"id": "ff338dcc-ccd4-41ca-848f-a39ab450ba82", "text": "Párhuzamos a szög száival", "isCorrect": false}], "timeLimit": 15}, {"id": "83ce76ae-7beb-417f-9766-3cfb13aa15a0", "text": "A szögfelező egyenes a szög szimmetriatengelye.", "type": "true-false", "options": [{"id": "445bcd25-a6c7-4ecf-b6bd-5d108a6801bf", "text": "Igaz", "isCorrect": true}, {"id": "7e82814d-224f-49bd-897b-922fadae9571", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "decabc90-8967-45f9-a844-72e110ac25c5", "text": "Hány szimmetriatengelye van egy 60°-os szögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "e85bf229-c8d2-4a61-854e-644a12982ce8", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "cb5a36ce-0f93-4a60-aebc-c851b25d9246", "text": "Végtelen sok (minden középponton átmenő egyenes)", "isCorrect": true}, {"id": "05a8e0b0-8b0d-4f7e-9317-debbcf25c013", "text": "1", "isCorrect": false}, {"id": "244ba5b2-46c5-4534-b166-4e88caf2d76b", "text": "2", "isCorrect": false}, {"id": "7a3ee248-40e3-46af-87ea-d16b79bb3edd", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "ca3deaa5-88f3-43fe-9768-e6dcc7110910", "text": "A szögfelező megszerkesztéséhez körzőíveket használunk a szög szárain.", "type": "true-false", "options": [{"id": "5c544986-507a-48a8-bca4-4d355df954d6", "text": "Igaz", "isCorrect": true}, {"id": "78ffce5e-35f7-4338-b9da-9d1462e19be1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d1bb67cb-7b16-478c-add4-45f57b2b2fbe", "text": "Hány fokos két 30°-os részre osztja a szögfelező a 60°-os szöget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW()),
('d2012bf3-cd03-48ed-8ec0-4206babe8656', '21feff02-016d-46e2-bb9d-c27495133b1b', '61. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek', 'Egyenlő szárú háromszög tulajdonságai és szimmetriatengelye.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "c6a0c7cb-550e-4b38-b470-f2969f0f4162", "text": "Hány szimmetriatengelye van az egyenlő szárú (nem egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "1ae18052-d177-45eb-9407-bc0e23da12c8", "text": "Hány szimmetriatengelye van a szabályos (egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "97dfddde-56f0-42b6-b8ea-0a8d24504a57", "text": "Az egyenlő szárú háromszög alapon fekvő szögei egyenlők.", "type": "true-false", "options": [{"id": "e4eedfe4-ac1e-400b-b4af-b2fa31501570", "text": "Igaz", "isCorrect": true}, {"id": "27cf4caa-d17f-4fbc-a976-24a3baf66e9f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3f78e41c-7340-41bd-ba35-7e2be851511d", "text": "Ha az egyenlő szárú háromszög szárai 8 cm-esek, és alapja 5 cm, mennyi a kerülete? (8+8+5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "21"}, {"id": "edbe9726-33c6-45cf-932c-34800daa06e7", "text": "Ha az egyenlő szárú háromszög szárszöge (csúcsszöge) 40°, mekkorák az alapon fekvő szögek? ((180-40)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "d549b947-4080-4d70-87a2-9344543d4cf6", "text": "Az egyenlő szárú háromszög szimmetriatengelye az alap felezőmerőlegese és a szárszög felezője is egyben.", "type": "true-false", "options": [{"id": "e020f09f-b0ca-4e65-8bf0-6d0909c0a95e", "text": "Igaz", "isCorrect": true}, {"id": "df63a0fd-d212-4fdb-9f56-c6ec47dcc83e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d090e062-04e4-45bd-9c40-dfe583610315", "text": "Az egyenlő oldalú háromszög minden szöge 60°-os.", "type": "true-false", "options": [{"id": "92ef53b2-d90b-4565-945d-1c3d596dea72", "text": "Igaz", "isCorrect": true}, {"id": "80267d73-771f-4164-839b-f660c564ecc7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('d7ead057-1b7f-4235-ab9e-a773333756fb', '21feff02-016d-46e2-bb9d-c27495133b1b', '62. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek II.', 'Tengelyesen szimmetrikus négyszögek (téglalap, négyzet, rombusz, deltoid, szimmetrikus trapéz) szimmetriatengelyei.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "16788c9f-2239-4a17-9f52-80bef427243d", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "4248d65a-12f9-4dd4-933b-8e667b2a4ba1", "text": "Hány szimmetriatengelye van a téglalapnak (ami nem négyzet)? (az oldalfelező merőlegesek)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "c27e0f45-8fcd-42f2-913f-27d588c04b60", "text": "Hány szimmetriatengelye van a rombusznak (ami nem négyzet)? (az átlók egyenesei)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "f554f160-8f91-41b8-8d0a-2390cb7447a0", "text": "Hány szimmetriatengelye van a deltoidnak (ha nem rombusz)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "bf0e2879-d4aa-41eb-9c4b-c9a152bfb9c2", "text": "A szimmetrikus (egyenlő szárú) trapéznak 1 szimmetriatengelye van.", "type": "true-false", "options": [{"id": "cc532af2-9a44-4f92-aab5-548e467c8352", "text": "Igaz", "isCorrect": true}, {"id": "ce83d517-2cba-4879-88ae-43ebdbffeb6e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b4fa1bfd-f33b-471f-b534-bf245ebae973", "text": "Az általános paralelogrammának (ami nem rombusz és nem téglalap) NINCS tengelyes szimmetriatengelye.", "type": "true-false", "options": [{"id": "0a5bd549-6658-41c9-985f-bc61d6220383", "text": "Igaz (középpontosan szimmetrikus, de tengelyesen nem)", "isCorrect": true}, {"id": "83397df7-91fc-43e1-90bf-fc9b84db280d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c96e8400-63c1-49e7-ae83-5c4c4d36493c", "text": "Hány szimmetriaten