('c026862f-689d-4e34-930f-602692252b8b', '21feff02-016d-46e2-bb9d-c27495133b1b', '67. óra: Témazáró dolgozat értékelése', 'A geometriai témazáró megbeszélése, szerkesztések értékelése és hibajavítás.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "ae00e99a-32a0-49df-9071-b15ea16bb682", "text": "Mi volt a leggyakoribb hiba a szerkesztési feladatok során?", "type": "multiple-choice", "options": [{"id": "8103c886-045f-4c23-8e24-0a0469d06b0b", "text": "A körző pontatlan használata és a háromszög-egyenlőtlenség figyelmen kívül hagyása", "isCorrect": true}, {"id": "10cfee4a-685a-442c-9095-84b3a1a183e6", "text": "A ceruza színe", "isCorrect": false}, {"id": "591988fd-7c9d-41b1-a7c2-7c92aef55ab6", "text": "A füzet vonalazása", "isCorrect": false}, {"id": "e480cf2c-7e4b-476b-9843-d57f2cc62ea7", "text": "A számok leírása", "isCorrect": false}], "timeLimit": 15}, {"id": "6d3c1dfb-5614-4875-82ac-0e15880578c7", "text": "A szakaszfelező merőleges merőleges a szakaszra és átmegy a felezőpontján.", "type": "true-false", "options": [{"id": "d44812cf-c750-4280-b245-766adacd9291", "text": "Igaz", "isCorrect": true}, {"id": "7fe5d4e7-dbdb-4bb4-9e0f-b10a86141286", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f2dc57d5-302c-440d-b3c3-2d1a9252bd87", "text": "Mennyi a kör átmérője, ha a sugara 10 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "1b69a4c8-49ae-489b-bcf3-69c5acc9375f", "text": "A tengelyes tükrözés során a síkidom területe nem változik.", "type": "true-false", "options": [{"id": "31554499-0641-413b-a7bb-d87ab117b1bf", "text": "Igaz", "isCorrect": true}, {"id": "48646cb6-5b3b-467f-b049-4d6f19a48643", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fb6f101f-a563-4b55-b90c-7c68f828ed51", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "fc7d985a-2f57-4689-a868-2ffad723fe4e", "text": "Végtelen sok", "isCorrect": true}, {"id": "1209aee0-7be1-4d6f-95ba-bb9bd5746bfb", "text": "1", "isCorrect": false}, {"id": "b7a65f93-6d0d-47ff-a6b1-539d09b5c50e", "text": "2", "isCorrect": false}, {"id": "e6a5520e-dc48-4169-a53a-9ad6439bb0d5", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "9f4de3f0-5695-424c-90f2-60e4b8b74b86", "text": "A pontos vázlatkészítés megkönnyíti a bonyolultabb szerkesztések elvégzését.", "type": "true-false", "options": [{"id": "afde023e-3eb3-4c96-8c08-73bc4b605ae2", "text": "Igaz", "isCorrect": true}, {"id": "762a715c-f403-4075-9687-e7b4d2e2b227", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "375a98fa-87dc-4618-ac9f-c491057f47a5", "text": "Mennyi a háromszög harmadik szöge, ha az első kettő 50° és 70°?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW()),
('9a86136e-57fe-496a-951c-4c9e9064d657', '21feff02-016d-46e2-bb9d-c27495133b1b', '68. óra: Az arány fogalma', 'Az arány fogalma, felírása kettősponttal és törttel, értelmezése hétköznapi példákban.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "e0fdca32-adf9-4e4f-bc6e-df84f8017293", "text": "Mit fejez ki két mennyiség aránya?", "type": "multiple-choice", "options": [{"id": "e7668b81-4db2-42fb-b606-57c0301fc310", "text": "Megmutatja, hányszorosa az egyik mennyiség a másiknak (hányadosukat)", "isCorrect": true}, {"id": "b8b2f98b-c9b9-4af2-8b54-d9bfc1a33986", "text": "Megmutatja a két mennyiség összegét", "isCorrect": false}, {"id": "6ec4821e-fbed-4455-8bdd-608ade81a471", "text": "Megmutatja a két mennyiség szorzatát", "isCorrect": false}, {"id": "e80611aa-9378-4fe4-a002-e56e8da529d6", "text": "Nem fejez ki semmit", "isCorrect": false}], "timeLimit": 15}, {"id": "86129f8d-e5ac-4fb2-a3c7-2edbe4651fa1", "text": "Hogyan jelöljük az arányt matematikailag?", "type": "multiple-choice", "options": [{"id": "ffb6e3aa-b95c-41bb-b5a0-66205d50356a", "text": "Kettősponttal (pl. 2 : 3) vagy törttel (2/3)", "isCorrect": true}, {"id": "a3e089b0-9734-4964-a16f-51bb41579a24", "text": "Plusz jellel", "isCorrect": false}, {"id": "571551de-1811-4bb0-8853-ddbc6f449268", "text": "Csillaggal", "isCorrect": false}, {"id": "6f10d9ff-150d-454b-b726-225cff45ae0f", "text": "Egyenlőségjellel", "isCorrect": false}], "timeLimit": 15}, {"id": "0f200f66-7332-44e8-8b43-bbbb61c99558", "text": "Ha egy osztályban 10 fiú és 15 lány van, mi a fiúk és lányok számának aránya legegyszerűbb alakban?", "type": "multiple-choice", "options": [{"id": "b578bdae-00d6-4a0a-9c3d-962259b559c6", "text": "2 : 3 (10/15 egyszerűsítve 5-tel)", "isCorrect": true}, {"id": "a2c3e87d-914c-4e81-a813-7a6bd57b6a9d", "text": "1 : 2", "isCorrect": false}, {"id": "4b053f19-6d0f-4805-b229-16935a3e7341", "text": "3 : 2", "isCorrect": false}, {"id": "8e29505b-6651-4aa0-97c3-fd9cd10fd9ca", "text": "10 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "ab897443-df2e-4f58-8330-dbfcafdc4505", "text": "Az arány a törtekhez hasonlóan egyszerűsíthető és bővíthető.", "type": "true-false", "options": [{"id": "c005179c-810a-4f16-b76e-ed6654073316", "text": "Igaz", "isCorrect": true}, {"id": "b8e32e94-8e48-422d-8d1c-971e7210f2c6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "59fc56e9-17be-45e7-85b8-b6b5acbbf104", "text": "Mennyi a 4 : 8 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "a70e93f0-6110-4b9c-bfec-e3bc6abeb93a", "text": "1 : 2", "isCorrect": true}, {"id": "4ccc82fd-0897-4915-9300-39443e3b92a7", "text": "2 : 4", "isCorrect": false}, {"id": "46e4da46-5cd4-45bb-bfb0-758f1b21769f", "text": "1 : 4", "isCorrect": false}, {"id": "e5b2359c-0c2a-45ba-99cf-d602ac45f58c", "text": "4 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "dd67e03c-a69a-4ff7-bc2d-21325100e0d5", "text": "Ha az arány 3 : 1, az első mennyiség 3-szor akkora, mint a második.", "type": "true-false", "options": [{"id": "e0afc9d8-76d2-4c84-a7a5-0517b16bdf2e", "text": "Igaz", "isCorrect": true}, {"id": "41dabf58-03d2-4b41-9aed-ea4fdda1d37c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e0b3d8d2-d0e1-45f9-8d0a-fbc4f2e6d70e", "text": "Melyik arány egyenlő az 1 : 2 aránnyal?", "type": "multiple-choice", "options": [{"id": "3d41911e-565c-40ee-9cf3-4b296d3f634d", "text": "5 : 10", "isCorrect": true}, {"id": "3956e04e-6d39-47eb-9873-b2a5b799e922", "text": "2 : 1", "isCorrect": false}, {"id": "4fc36b2a-f90f-49af-b77a-8659a9d02b4c", "text": "3 : 5", "isCorrect": false}, {"id": "53294eae-d418-4eab-9d0e-520657de1bb6", "text": "4 : 6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('ab5bbe07-d939-44f3-a37e-c40329fb792e', '21feff02-016d-46e2-bb9d-c27495133b1b', '69. óra: Arányos osztás', 'Adott mennyiség felosztása megadott arányban (pl. 2 : 3 arányban).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "72b93e79-e2d2-4a0b-a4a0-04c2611208aa", "text": "Ha 500 Ft-ot elosztunk 2 : 3 arányban, hány egyenlő részre osztjuk először a teljes összeget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "3fb43d25-37bd-46b5-82fe-875e369ca4dc", "text": "Hány Ft a kisebbik rész 500 Ft 2 : 3 arányú felosztásakor? (1 rész = 100 Ft, 2 rész = 200 Ft)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "f26d65b7-b895-4a1c-b4b5-c8396696fc47", "text": "Hány Ft a nagyobbik rész 500 Ft 2 : 3 arányú felosztásakor? (3 rész = 300 Ft)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "388f8a3b-ccf4-4ef8-affc-34ef702cfd87", "text": "Az arányos osztásnál az arányszámok összege megadja az összes egység (rész) számát.", "type": "true-false", "options": [{"id": "dcbdc28b-48e0-4bdf-a6b4-c65b0d22f20f", "text": "Igaz", "isCorrect": true}, {"id": "9acdac36-b79c-4a99-a627-c7934ca1a0cb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fab09668-f4da-4cd8-b5dd-9e4ef01c7406", "text": "Ossz el 30 szem cukorkát 1 : 2 arányban! Hány cukorka a nagyobbik adag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "b5cdf02c-ae81-4c8a-bc93-82c7c4dc962a", "text": "Ossz el 30 szem cukorkát 1 : 2 arányban! Hány cukorka a kisebbik adag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "03d23d35-66eb-42fd-9d2f-f1d17d6ec9b1", "text": "Az arányos osztási feladatok ellenőrizhetők a kapott részek összegzésével.", "type": "true-false", "options": [{"id": "645c76ad-ded7-4bfb-95cf-91af2fcb7c82", "text": "Igaz", "isCorrect": true}, {"id": "aa2f171f-ce28-4dbf-9f49-7aeafd8ffe8a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('58c7d944-c065-4355-a055-5dea57af63ca', '21feff02-016d-46e2-bb9d-c27495133b1b', '70. óra: Feladatok megoldása', 'Hétköznapi recept, ötvözet, keverék és arányos osztási feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "77c38909-0f87-44ea-9799-54544881cb93", "text": "Egy habarcs készítéséhez homok és mész kell 4 : 1 arányban. Hány kg homok kell 50 kg habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "90aa9fca-0c58-4e8e-a2bf-cd7f23350115", "text": "Egy szörp elkészítéséhez szörp és víz kell 1 : 4 arányban. Hány dl szörp kell 10 dl (1 liter) italhoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "d0f765ff-0c14-4a70-a96a-13f6d4ce66ee", "text": "Ha két testvér 3 : 5 arányban osztozik 800 Ft-on, a nagyobbik rész 500 Ft.", "type": "true-false", "options": [{"id": "27f3a5cd-aee1-4ef8-8d7d-a13d1b4ce346", "text": "Igaz (800 / 8 = 100, 5 * 100 = 500)", "isCorrect": true}, {"id": "4836cdb6-2536-40bc-80a2-3bc24c1f6220", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3df56db4-5064-43fb-8d96-c43562cb9968", "text": "Egy téglalap két szomszédos oldalának aránya 2 : 3. Ha a rövidebb oldal 6 cm, hány cm a hosszabb oldal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "0621c35e-c675-4ce0-a6b4-9d70569dc264", "text": "Melyik állítás igaz az arányos osztásra?", "type": "multiple-choice", "options": [{"id": "d6ee3c02-fcc7-4066-b2ec-cc282f5e0034", "text": "A kapott részek aránya megegyezik a megadott aránnyal", "isCorrect": true}, {"id": "9486e218-ad39-4c3a-8e0a-c639ae1a38e6", "text": "Minden rész egyenlő nagyságú", "isCorrect": false}, {"id": "53c70634-4da7-4387-8b39-997b858d0a97", "text": "A részek összege kisebb az eredeti mennyiségnél", "isCorrect": false}, {"id": "975707d8-f066-4826-a4f9-af804a11918a", "text": "Nem lehet kiszámolni", "isCorrect": false}], "timeLimit": 15}, {"id": "eb00a00b-a90b-4437-b35f-e76c93b999c1", "text": "Hány g mész kell 50 kg (4:1 arányú) habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "b2e4853f-a625-45af-80ff-723166fc1612", "text": "A receptekben megadott hozzávalók aránya lehetővé teszi tetszőleges adag elkészítését.", "type": "true-false", "options": [{"id": "26c57da6-663f-481a-85d3-4ebde7eebd87", "text": "Igaz", "isCorrect": true}, {"id": "c091a66e-0605-4dac-83d0-8a37eb122313", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());